                "type": "object",
                "properties": {
                    "wrapper": {
                        "type": "object",
                        "properties": {
                            "inner": { "type": "string", "description": "inner field" }
                        },
                        "required": ["inner"]
                    }
                },
                "required": ["wrapper"]
            }),
        );
        let derived = plugin_schema_from_json(
            "nested_test",
