/// The single active-schema catalog in shared memory. Every plugin reads its
/// own slice by name from this one file — there is no per-plugin shm file and
/// no diff loop. The schema's declared state IS the desired state.
const SHM_SCHEMA_PATH: &str = "/dev/shm/live-schema.json";

fn default_protocol() -> String {
    "grpc".to_string()
}

/// A configured unix-domain socket endpoint.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct SocketEndpoint {
    /// Filesystem path to the socket.
    #[schemars(
        description = "Filesystem path of the unix domain socket",
        example = &"/run/qdrant.sock",
        extend("x-oscal-subid" = "mut.service.unix_socket.bind-path@v1")
    )]
    pub path: String,
    /// Local TCP port xray listens on and proxies into this socket.
    #[schemars(
        range(min = 1, max = 65535),
        description = "Local TCP port xray listens on and proxies into this socket",
        example = 6334,
        extend("x-oscal-subid" = "mut.service.unix_socket.bind-port@v1")
    )]
    pub port: u16,
    /// Transport protocol carried over the socket.
    #[serde(default = "default_protocol")]
    #[schemars(
        description = "Transport protocol carried over the socket (grpc, jsonrpc, …)",
        extend("x-oscal-subid" = "mut.service.unix_socket.bind-protocol@v1")
    )]
    pub protocol: String,
    /// Human-readable service label.
    #[serde(default)]
    #[schemars(
        description = "Human-readable service label used as the xray outbound tag",
        example = &"qdrant-grpc",
        extend("x-oscal-subid" = "mut.service.unix_socket.bind-label@v1")
